"""JWT session management for Noko."""

from datetime import datetime, timedelta, timezone
from uuid import uuid4

import jwt
from sqlalchemy import select

from src.config import settings

ALGORITHM = "HS256"


class InvalidTokenError(Exception):
    """Raised when a token is expired, malformed, or tampered with."""


def create_token(
    family_id: str,
    member_id: str,
    role: str,
    token_version: int = 1,
    expires_minutes: int = 60,
) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "family_id": family_id,
        "member_id": member_id,
        "role": role,
        "token_version": token_version,
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_token(token: str) -> dict:
    try:
        return jwt.decode(token, settings.secret_key, algorithms=[ALGORITHM])
    except jwt.PyJWTError as e:
        raise InvalidTokenError(str(e)) from e


def create_magic_link_token(email: str, expires_minutes: int = 15) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "email": email,
        "purpose": "magic_link",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_magic_link_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "magic_link":
        raise InvalidTokenError("Not a magic link token")
    return claims


def create_invite_token(
    family_id: str,
    role: str,
    intended_email: str | None = None,
    expires_hours: int = 24,
) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "family_id": family_id,
        "role": role,
        "purpose": "invite",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(hours=expires_hours),
    }
    if intended_email is not None:
        payload["intended_email"] = intended_email
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_invite_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "invite":
        raise InvalidTokenError("Not an invite token")
    return claims


def create_family_select_token(email: str, expires_minutes: int = 5) -> str:
    """Short-lived token for multi-family users to select which family to enter."""
    now = datetime.now(timezone.utc)
    payload = {
        "email": email,
        "purpose": "family_select",
        "jti": str(uuid4()),
        "iat": now,
        "exp": now + timedelta(minutes=expires_minutes),
    }
    return jwt.encode(payload, settings.secret_key, algorithm=ALGORITHM)


def verify_family_select_token(token: str) -> dict:
    claims = verify_token(token)
    if claims.get("purpose") != "family_select":
        raise InvalidTokenError("Not a family select token")
    return claims


async def bump_token_version(db, member_id: str) -> None:
    """Increment a member's token_version, invalidating all outstanding JWTs.

    Call this when a member's role changes or when they are removed from a family.
    Caller must commit the session.
    """
    from src.models import Member  # deferred to avoid circular import

    result = await db.execute(select(Member).where(Member.id == member_id))
    member = result.scalar_one_or_none()
    if member is not None:
        member.token_version += 1
